(()=>{(function(){"use strict";function e(){try{let n=document.getElementById("script-configure-datadog-context");if(!n){console.warn("[Datadog] Elemento de configuraci\xF3n no encontrado");return}let t=n.getAttribute("data-obj");if(!t){console.warn("[Datadog] Atributo data-obj ausente");return}let r;try{r=JSON.parse(t)}catch(o){console.warn("[Datadog] Error al parsear data-obj",o);return}let a="fusion_info";if(window.DD_LOGS?.onReady)try{window.DD_LOGS.onReady(()=>{window.DD_LOGS.logger.setContextProperty(a,r)})}catch(o){console.warn("[Datadog] Error al configurar DD_LOGS",o)}else console.warn("[Datadog] DD_LOGS no disponible");if(window.DD_RUM?.onReady)try{window.DD_RUM.onReady(()=>{window.DD_RUM.setGlobalContextProperty(a,r)})}catch(o){console.warn("[Datadog] Error al configurar DD_RUM",o)}else console.warn("[Datadog] DD_RUM no disponible")}catch(n){console.warn("[Datadog] Error inesperado en configuraci\xF3n",n)}}setTimeout(e,0)})();})();
